## Making HTTP Requests

### Basic GET Request

```xiom
use xiom.http;

fn main() -> Int {
  let response = http::get("https://api.example.com/users/1")?;

  io.println("Status: " + response.status.to_str());
  io.println("Body: " + response.body);

  if response.is_success() {
    let user: User = json::from_str(&response.body)?;
    process_user(&user);
  }
  return 0;
}
```

### POST Request with JSON

```xiom
fn create_user(name: Str, email: Str) -> Result<User, Error> {
  let payload = json::to_string(&{
    name: name,
    email: email,
  });

  let response = http::post("https://api.example.com/users")
    .header("Content-Type", "application/json")
    .header("Authorization", "Bearer " + api_token)
    .body(payload)
    .send()?;

  if !response.is_success() {
    return Err("Failed to create user: " + response.status.to_str());
  }

  return json::from_str(&response.body);
}
```

### Request Builder

```xiom
let client = http::Client::new()
  .timeout(30_000)  // 30 seconds
  .user_agent("MyApp/1.0")
  .max_redirects(5);

let response = client
  .get("https://api.example.com/data")
  .query("page", "1")
  .query("limit", "50")
  .send()?;
```

### Error Handling

```xiom
fn fetch_with_retry(url: &Str, max_retries: Int) -> Result[Str, Error] {
  for attempt in 0..max_retries {
    match http::get(url) {
      Ok(response) if response.is_success() => return Ok(response.body),
      Ok(response) => io.eprintln("Server error: " + response.status.to_str()),
      Err(e) => io.eprintln("Network error: " + e.to_str()),
    }
    os.sleep(2u64.pow(attempt));  // Exponential backoff
  }
  return Err("All retries failed");
}
```

### Async HTTP

```xiom
async fn fetch_all(urls: &Vec[Str]) -> Vec[Str] {
  let mut futures = Vec[Future[Str]]();
  for url in urls {
    futures.push(async {
      let response = http::get(url).await?;
      return response.body;
    });
  }
  return futures::join_all(futures).await;
}
```

